import type { StyleSpecification } from 'maplibre-gl';

/**
 * The look of our world, and the whole of it: sea, land, lakes, rivers, and not one word of text.
 *
 * There is no tile service behind this. The geometry is the warped Earth generated by the world package
 * and served as three files, which is why the map can be stylised freely and why it shows no roads,
 * no towns and no borders. See docs/adr/0017.
 */

const PALETTE = {
  sea: '#aabec7',
  seaDeep: '#9fb4be',
  land: '#ece2cd',
  coast: '#6d6047',
  river: '#8ba7b3',
} as const;

/** Natural Earth at this scale has no more detail to give past about this zoom. */
export const WORLD_MAX_ZOOM = 10;

export function warpedWorldStyle(): StyleSpecification {
  const geojson = (path: string) => ({ type: 'geojson', data: path, maxzoom: WORLD_MAX_ZOOM }) as const;

  return {
    version: 8,
    name: 'Villages',
    sources: {
      land: geojson('/world/land.geojson'),
      lakes: geojson('/world/lakes.geojson'),
      rivers: geojson('/world/rivers.geojson'),
    },
    layers: [
      {
        id: 'sea',
        type: 'background',
        paint: { 'background-color': PALETTE.sea },
      },
      {
        id: 'land',
        type: 'fill',
        source: 'land',
        paint: { 'fill-color': PALETTE.land },
      },
      {
        id: 'coast',
        type: 'line',
        source: 'land',
        paint: {
          'line-color': PALETTE.coast,
          'line-opacity': 0.75,
          'line-width': ['interpolate', ['linear'], ['zoom'], 2, 0.5, 6, 1.1, 10, 2],
        },
      },
      {
        id: 'lakes',
        type: 'fill',
        source: 'lakes',
        paint: { 'fill-color': PALETTE.seaDeep },
      },
      {
        id: 'rivers',
        type: 'line',
        source: 'rivers',
        paint: {
          'line-color': PALETTE.river,
          'line-opacity': 0.85,
          'line-width': ['interpolate', ['linear'], ['zoom'], 3, 0.4, 7, 1.2, 10, 2.4],
        },
      },
    ],
  };
}
